-- Unused paid CARD credit: original capture, approved whole-lot reservation,
-- single refund attempt and an append-only zero-revenue liability reversal.
CREATE TABLE nc_prepaid_refunds(
 id TEXT PRIMARY KEY,grant_id TEXT NOT NULL REFERENCES nc_prepaid_grants(id),subscription_id TEXT NOT NULL REFERENCES nc_subscriptions(id),customer_id TEXT NOT NULL REFERENCES nc_customers(id),purchase_invoice_id TEXT NOT NULL REFERENCES nc_invoices(id),payment_id TEXT NOT NULL REFERENCES nc_payments(id),
 amount_n INTEGER NOT NULL CHECK(typeof(amount_n)='integer' AND amount_n>0),amount_cents INTEGER NOT NULL CHECK(typeof(amount_cents)='integer' AND amount_cents>0),quote_json TEXT NOT NULL CHECK(json_valid(quote_json)),basis_hash TEXT NOT NULL,reason TEXT NOT NULL,
 prepared_by_id TEXT NOT NULL REFERENCES nc_members(id),prepared_at INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','rejected','approved','claimed','uncertain','refunded','failed','stopped')),intent_key TEXT NOT NULL UNIQUE,revision TEXT NOT NULL,
 approved_by_id TEXT REFERENCES nc_members(id),approved_at INTEGER,approval_mode TEXT,claimed_at INTEGER,refund_ref TEXT UNIQUE,proof_json TEXT CHECK(proof_json IS NULL OR json_valid(proof_json)),credit_id TEXT UNIQUE REFERENCES nc_credit_notes(id),ledger_id TEXT UNIQUE REFERENCES nc_prepaid_ledger(id),refunded_on TEXT,error_code TEXT,
 CHECK(status NOT IN ('approved','claimed','uncertain','refunded','failed','stopped') OR (approved_by_id IS NOT NULL AND approved_at IS NOT NULL AND approval_mode IN ('single-approver','two-person'))),
 CHECK(status<>'refunded' OR (refund_ref IS NOT NULL AND proof_json IS NOT NULL AND credit_id IS NOT NULL AND ledger_id IS NOT NULL AND refunded_on IS NOT NULL)));
CREATE UNIQUE INDEX nc_prepaid_refund_active ON nc_prepaid_refunds(grant_id) WHERE status IN ('pending','approved','claimed','uncertain');
CREATE TABLE nc_prepaid_refund_credits(credit_id TEXT PRIMARY KEY REFERENCES nc_credit_notes(id),refund_id TEXT NOT NULL UNIQUE REFERENCES nc_prepaid_refunds(id),customer_id TEXT NOT NULL REFERENCES nc_customers(id),purchase_invoice_id TEXT NOT NULL REFERENCES nc_invoices(id),purpose TEXT NOT NULL CHECK(purpose='paid-liability-cash-refund'));
CREATE TRIGGER nc_prepaid_refund_reservation BEFORE INSERT ON nc_prepaid_ledger WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND NEW.kind<>'refund' AND EXISTS(SELECT 1 FROM nc_prepaid_refunds WHERE grant_id=NEW.grant_id AND status IN ('approved','claimed','uncertain')) BEGIN SELECT RAISE(ABORT,'nectar_guard_prepaid_refund_reserved'); END;
CREATE TRIGGER nc_prepaid_refund_ledger_source BEFORE INSERT ON nc_prepaid_ledger WHEN NEW.kind='refund' AND NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND NOT EXISTS(SELECT 1 FROM nc_prepaid_refunds r WHERE NEW.id=r.id||'-refund' AND r.grant_id=NEW.grant_id AND r.customer_id=NEW.customer_id AND r.subscription_id=NEW.subscription_id AND r.status='uncertain' AND json_extract(r.proof_json,'$.proof')='succeeded-refund-and-balance-debit' AND NEW.amount_n=-r.amount_n AND NEW.liability_cents=-r.amount_cents AND NEW.recognition_cents=0 AND NEW.purchase_invoice_id=r.purchase_invoice_id) BEGIN SELECT RAISE(ABORT,'nectar_guard_prepaid_refund_proof_required'); END;
CREATE TRIGGER nc_prepaid_refund_credit_source BEFORE INSERT ON nc_prepaid_refund_credits WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND NOT EXISTS(SELECT 1 FROM nc_prepaid_refunds r JOIN nc_credit_notes n ON n.id=NEW.credit_id WHERE r.id=NEW.refund_id AND r.customer_id=NEW.customer_id AND r.purchase_invoice_id=NEW.purchase_invoice_id AND r.status='uncertain' AND json_extract(r.proof_json,'$.proof')='succeeded-refund-and-balance-debit' AND n.invoice_id=r.purchase_invoice_id AND n.customer_id=r.customer_id AND n.amount_cents=r.amount_cents AND n.applied_cents=0 AND n.subtotal_cents=r.amount_cents AND n.tax_cents=0) BEGIN SELECT RAISE(ABORT,'nectar_guard_prepaid_refund_credit_required'); END;
CREATE TRIGGER nc_prepaid_refund_insert BEFORE INSERT ON nc_prepaid_refunds WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND (NEW.status<>'pending' OR NEW.approved_at IS NOT NULL OR NEW.refund_ref IS NOT NULL OR NOT EXISTS(SELECT 1 FROM nc_prepaid_grants g JOIN nc_payments p ON p.id=NEW.payment_id WHERE g.id=NEW.grant_id AND g.subscription_id=NEW.subscription_id AND g.customer_id=NEW.customer_id AND g.source='purchase' AND g.purchase_invoice_id=NEW.purchase_invoice_id AND p.customer_id=g.customer_id AND p.method='card_external')) BEGIN SELECT RAISE(ABORT,'nectar_guard_prepaid_refund_source_changed'); END;
CREATE TRIGGER nc_prepaid_refund_update BEFORE UPDATE ON nc_prepaid_refunds WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND (
 OLD.id IS NOT NEW.id OR OLD.grant_id IS NOT NEW.grant_id OR OLD.subscription_id IS NOT NEW.subscription_id OR OLD.customer_id IS NOT NEW.customer_id OR OLD.purchase_invoice_id IS NOT NEW.purchase_invoice_id OR OLD.payment_id IS NOT NEW.payment_id OR OLD.amount_n IS NOT NEW.amount_n OR OLD.amount_cents IS NOT NEW.amount_cents OR OLD.quote_json IS NOT NEW.quote_json OR OLD.basis_hash IS NOT NEW.basis_hash OR OLD.reason IS NOT NEW.reason OR OLD.prepared_by_id IS NOT NEW.prepared_by_id OR OLD.prepared_at IS NOT NEW.prepared_at OR OLD.intent_key IS NOT NEW.intent_key
 OR OLD.status IN ('rejected','refunded','failed','stopped') OR (OLD.refund_ref IS NOT NULL AND OLD.refund_ref IS NOT NEW.refund_ref)
 OR (OLD.approved_at IS NOT NULL AND (OLD.approved_at IS NOT NEW.approved_at OR OLD.approved_by_id IS NOT NEW.approved_by_id OR OLD.approval_mode IS NOT NEW.approval_mode))
 OR NOT((OLD.status='pending' AND NEW.status IN ('approved','rejected')) OR (OLD.status='approved' AND NEW.status IN ('claimed','stopped')) OR (OLD.status IN ('claimed','uncertain') AND NEW.status IN ('uncertain','refunded','failed','stopped')))
 OR (NEW.status='approved' AND NOT EXISTS(SELECT 1 FROM nc_members p JOIN nc_members a ON a.id=NEW.approved_by_id WHERE p.id=NEW.prepared_by_id AND p.role='owner' AND p.status='active' AND a.role IN ('owner','finance') AND a.status='active' AND (p.id<>a.id OR NEW.approval_mode='single-approver' AND NOT EXISTS(SELECT 1 FROM nc_members WHERE id<>p.id AND status='active' AND role IN ('owner','finance')))))
 OR (NEW.status='refunded' AND NOT EXISTS(SELECT 1 FROM nc_prepaid_refund_credits x JOIN nc_prepaid_ledger l ON l.id=NEW.ledger_id WHERE x.refund_id=NEW.id AND x.credit_id=NEW.credit_id AND l.kind='refund' AND l.grant_id=NEW.grant_id AND l.amount_n=-NEW.amount_n AND l.liability_cents=-NEW.amount_cents AND l.recognition_cents=0))
) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;

CREATE TRIGGER nc_prepaid_refunds_generation_insert AFTER insert ON nc_prepaid_refunds BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_prepaid_refunds_generation_update AFTER update ON nc_prepaid_refunds BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_prepaid_refunds_generation_delete AFTER delete ON nc_prepaid_refunds BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_prepaid_refunds_owned_insert BEFORE insert ON nc_prepaid_refunds WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_customers WHERE id IN (NEW.customer_id) AND erased_at IS NOT NULL) BEGIN SELECT RAISE(ABORT,'nectar_guard_customer_erased'); END;
CREATE TRIGGER nc_prepaid_refunds_owned_update BEFORE update ON nc_prepaid_refunds WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_customers WHERE id IN (NEW.customer_id,OLD.customer_id) AND erased_at IS NOT NULL) BEGIN SELECT RAISE(ABORT,'nectar_guard_customer_erased'); END;
CREATE TRIGGER nc_prepaid_refunds_keep BEFORE DELETE ON nc_prepaid_refunds WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_prepaid_refund_credits_generation_insert AFTER insert ON nc_prepaid_refund_credits BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_prepaid_refund_credits_generation_update AFTER update ON nc_prepaid_refund_credits BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_prepaid_refund_credits_generation_delete AFTER delete ON nc_prepaid_refund_credits BEGIN UPDATE nc_privacy_generation SET value=value+1 WHERE id=1; END;
CREATE TRIGGER nc_prepaid_refund_credits_owned_insert BEFORE insert ON nc_prepaid_refund_credits WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_customers WHERE id IN (NEW.customer_id) AND erased_at IS NOT NULL) BEGIN SELECT RAISE(ABORT,'nectar_guard_customer_erased'); END;
CREATE TRIGGER nc_prepaid_refund_credits_owned_update BEFORE update ON nc_prepaid_refund_credits WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND EXISTS(SELECT 1 FROM nc_customers WHERE id IN (NEW.customer_id,OLD.customer_id) AND erased_at IS NOT NULL) BEGIN SELECT RAISE(ABORT,'nectar_guard_customer_erased'); END;
CREATE TRIGGER nc_prepaid_refund_credits_keep BEFORE DELETE ON nc_prepaid_refund_credits WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_prepaid_refund_credits_content BEFORE UPDATE ON nc_prepaid_refund_credits WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
